{
  "name": "AS7341多通道光谱传感器",
  "name_en": "AS7341 Multi-channel Spectral Sensor",
  "manufacturer": "",
  "description": "这是一种基于AS7341的多通道可见光光谱传感器，可对多个波段的光强进行采样并输出光谱读数。它适用于实验室中的颜色分析、光源表征、样品透射或反射光测量，以及需要快速获取离散波段光学信息的教学与原型实验。",
  "description_en": "This is a multi-channel visible-light spectral sensor based on the AS7341, designed to sample light intensity across multiple wavelength bands and report spectral readings. It is useful in laboratories for color analysis, light-source characterization, transmission or reflection measurements of samples, and teaching or prototyping tasks that need fast discrete-band optical data.",
  "tag_hints": [
    "spectral sensing",
    "visible light measurement",
    "multichannel photometry",
    "color sensing",
    "optical characterization",
    "AS7341"
  ],
  "actions": [
    {
      "action_name": "auto-load_config",
      "description": "加载设备连接与运行配置。",
      "description_en": "Load the device connection and operating configuration."
    },
    {
      "action_name": "auto-find_seeed",
      "description": "查找已连接的Seeed串口设备。",
      "description_en": "Find connected Seeed serial devices."
    },
    {
      "action_name": "auto-connect_seeed",
      "description": "连接到指定的Seeed设备。",
      "description_en": "Connect to the selected Seeed device."
    },
    {
      "action_name": "auto-disconnect_seeed",
      "description": "断开当前Seeed设备连接。",
      "description_en": "Disconnect the current Seeed device."
    },
    {
      "action_name": "auto-blink",
      "description": "触发设备闪烁以便识别。",
      "description_en": "Trigger the device to blink for identification."
    },
    {
      "action_name": "auto-measure_spectrum",
      "description": "测量各光谱通道的光强读数。",
      "description_en": "Measure light intensity readings across the spectral channels."
    },
    {
      "action_name": "auto-get_raw_spectrum",
      "description": "获取原始光谱数据字符串。",
      "description_en": "Get the raw spectrum data string."
    }
  ]
}

